			dw kw_ztov, var_pk

			; Main.bas 91: KeyIn k
			dw p_keyin_c, var_k

			; Main.bas 92: ElseIf wt = 0 Then
			dw if8_e_go
if8_1:
			dw kw_cpeqvl, var_wt, 0
			dw kw_goto_iffalse_n, if8_2

			; Main.bas 94: If front = 0 Or st(front) <> 2 Or kq(front) = 0 Then
			dw kw_cpeqvl, var_front, 0
			dw kw_ftov, tmp0
			dw kw_aget, arr_st, var_front, tmp1
			dw kw_cpnevl, tmp1, 2
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_aget, arr_kq, var_front, tmp1
			dw kw_cpeqvl, tmp1, 0
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, if8_e

			; Main.bas 95: k = Inkey
			dw kw_inkey, tmp0
